import { resolveDirectionAddress, withDirectionRefs } from './directionRefs';
import { nestedFreshSessionWorkdirs } from './historyRoots';
import type { ProjectLibrary } from './ProjectLibrary';
import type {
  VariantHistoryEntry,
  VariantHistoryService,
} from './VariantHistoryService';
import type {
  DirectionCandidate,
  DirectionRef,
  DirectionResolution,
  DirectionSearchAddress,
} from '../types/direction-ref';

export type ProjectDirectionSource =
  | { kind: 'library'; library: ProjectLibrary; projectId: string }
  | { kind: 'history'; history: VariantHistoryService; projectPath: string };

export type ProjectDirection = VariantHistoryEntry & {
  projectPath: string;
  directionRef: DirectionRef;
};

const listSourceEntries = async (
  source: ProjectDirectionSource,
): Promise<Array<VariantHistoryEntry & { projectPath: string }>> => {
  switch (source.kind) {
    case 'library':
      return source.library.listVariants(source.projectId, {
        isRemovedIncluded: true,
      });
    case 'history':
      return (
        await Promise.all(
          [
            source.projectPath,
            ...nestedFreshSessionWorkdirs(source.projectPath),
          ].map(async (projectPath) =>
            (await source.history.listVariants({ projectPath })).map(
              (entry) => ({ ...entry, projectPath }),
            ),
          ),
        )
      ).flat();
    default: {
      const unhandled: never = source;
      return unhandled;
    }
  }
};

export const listProjectDirections = async (
  source: ProjectDirectionSource,
): Promise<ProjectDirection[]> =>
  withDirectionRefs(await listSourceEntries(source));

const directionCandidateOf = (
  direction: ProjectDirection,
): DirectionCandidate => ({
  directionRef: direction.directionRef,
  sessionId: direction.manifest.sessionId,
  variantId: direction.manifest.variantId,
  label: direction.manifest.label,
  status: direction.manifest.status,
  createdAt: direction.manifest.createdAt,
});

export const resolveProjectDirection = async (args: {
  source: ProjectDirectionSource;
  address: DirectionSearchAddress;
}): Promise<DirectionResolution> =>
  resolveDirectionAddress({
    address: args.address,
    candidates: (await listProjectDirections(args.source)).map(
      directionCandidateOf,
    ),
  });
